-- #1318: inert Better Auth tables. Baseline from `npx auth@1.7.21 generate` (Kysely adapter), then COLLATE "C" and BIGINT unix-millisecond times.
-- auth_phone_registry is permanent: a row is never deleted when a user clears their phone. A second HMAC or user_id is refused.
CREATE TABLE IF NOT EXISTS auth_user(id TEXT COLLATE "C" PRIMARY KEY NOT NULL,name TEXT COLLATE "C" NOT NULL,email TEXT COLLATE "C" NOT NULL UNIQUE,email_verified BOOLEAN NOT NULL,image TEXT COLLATE "C",created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,phone_number TEXT COLLATE "C" UNIQUE,phone_number_verified BOOLEAN);
CREATE TABLE IF NOT EXISTS auth_session(id TEXT COLLATE "C" PRIMARY KEY NOT NULL,expires_at BIGINT NOT NULL,token TEXT COLLATE "C" NOT NULL UNIQUE,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,ip_address TEXT COLLATE "C",user_agent TEXT COLLATE "C",user_id TEXT COLLATE "C" NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS auth_account(id TEXT COLLATE "C" PRIMARY KEY NOT NULL,account_id TEXT COLLATE "C" NOT NULL,provider_id TEXT COLLATE "C" NOT NULL,user_id TEXT COLLATE "C" NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE,access_token TEXT COLLATE "C",refresh_token TEXT COLLATE "C",id_token TEXT COLLATE "C",access_token_expires_at BIGINT,refresh_token_expires_at BIGINT,scope TEXT COLLATE "C",password TEXT COLLATE "C",created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_verification(id TEXT COLLATE "C" PRIMARY KEY NOT NULL,identifier TEXT COLLATE "C" NOT NULL,value TEXT COLLATE "C" NOT NULL,expires_at BIGINT NOT NULL,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS auth_session_user_id_idx ON auth_session(user_id);
CREATE INDEX IF NOT EXISTS auth_account_user_id_idx ON auth_account(user_id);
CREATE INDEX IF NOT EXISTS auth_verification_identifier_idx ON auth_verification(identifier);
CREATE TABLE IF NOT EXISTS auth_phone_registry(phone_hmac TEXT COLLATE "C" PRIMARY KEY CHECK(phone_hmac ~ '^[0-9a-f]{64}$'),user_id TEXT COLLATE "C" NOT NULL UNIQUE CHECK(user_id <> ''),bound_at BIGINT NOT NULL CHECK(bound_at > 0),revoked_at BIGINT NULL CHECK(revoked_at IS NULL OR revoked_at >= bound_at));
